import{_ as t}from"./chunks/run-changes.BxnGjCua.js";import{_ as a}from"./chunks/test-case-detail.C5uQxYLf.js";import{_ as s,o as r,c as n,ak as i}from"./chunks/framework.sV-XtlWr.js";const y=JSON.parse('{"title":"Regression or flake?","description":"","frontmatter":{"title":"Regression or flake?","lang":"en-US"},"headers":[],"relativePath":"recipes/regression-or-flaky.md","filePath":"recipes/regression-or-flaky.md","lastUpdated":1788720938000}'),o={name:"recipes/regression-or-flaky.md"};function h(l,e,d,u,c,g){return r(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="is-this-test-failing-because-of-my-change-or-is-it-flaky" tabindex="-1">Is this test failing because of my change, or is it flaky? <a class="header-anchor" href="#is-this-test-failing-because-of-my-change-or-is-it-flaky" aria-label="Permalink to &quot;Is this test failing because of my change, or is it flaky?&quot;">​</a></h1><p>The most common question in a red CI run, and the most expensive one to answer wrong: re-run a real regression and you ship the bug; chase a flake and you lose an afternoon. Piwi answers it from history you already have, in about a minute.</p><h2 id="_1-open-the-run-s-changes-tab" tabindex="-1">1. Open the run&#39;s Changes tab <a class="header-anchor" href="#_1-open-the-run-s-changes-tab" aria-label="Permalink to &quot;1. Open the run&#39;s Changes tab&quot;">​</a></h2><p>A run compares itself against <strong>one baseline</strong> — the last passing run on the same branch by default — and sorts the failures for you. The distinction you want is right there in the headings:</p><ul><li><strong>New failures</strong> — this test was passing on the baseline and is failing now.</li><li><strong>Still failing</strong> — it was already failing before your change.</li><li><strong>Newly flaky / passed on retry</strong> — it passed but needed a retry.</li></ul><figure><img src="'+t+'" alt="Run Changes tab showing the baseline selector, new failures, fixed tests and the commits landed since the baseline"><figcaption>The Changes tab — read against one baseline, with new failures separated from tests that only passed on retry.</figcaption></figure><p>If your test is under <strong>Newly flaky / passed on retry</strong>, stop here: it isn&#39;t your change. Jump to <a href="./flaky-cleanup.html">cutting flakiness</a> when you have time to spend on it.</p><h2 id="_2-check-the-test-s-own-history" tabindex="-1">2. Check the test&#39;s own history <a class="header-anchor" href="#_2-check-the-test-s-own-history" aria-label="Permalink to &quot;2. Check the test&#39;s own history&quot;">​</a></h2><p>A single run can lie — a flaky test lands in &quot;new regressions&quot; whenever the baseline happened to be green. Open the test case and read its <strong>status history</strong> and <strong>stability trend</strong>: pass rate, flaky rate, and duration bucketed over time.</p><figure><img src="'+a+'" alt="Test case detail page with summary stats, duration trend, status history, and recent executions"><figcaption>Test case detail — the run-by-run status history is what separates &quot;this has always been shaky&quot; from &quot;this broke on Tuesday&quot;.</figcaption></figure><p>Read it like this:</p><table tabindex="0"><thead><tr><th>History looks like</th><th>Verdict</th></tr></thead><tbody><tr><td>Solid green, then red from one run onward</td><td>A regression. Find the commit in that gap.</td></tr><tr><td>Red/green alternating for weeks</td><td>A flake that happened to fail on your run.</td></tr><tr><td>Green, then red, and the failing execution <strong>passed on retry</strong></td><td>A flake — the <code>passed on retry</code> chip is on the execution&#39;s Verdict card.</td></tr><tr><td>Newly red <em>and</em> the failure is shared with other tests</td><td>Probably neither — see <a href="./mass-failure.html">triaging a mass failure</a>.</td></tr></tbody></table><h2 id="_3-find-what-changed-around-it" tabindex="-1">3. Find what changed around it <a class="header-anchor" href="#_3-find-what-changed-around-it" aria-label="Permalink to &quot;3. Find what changed around it&quot;">​</a></h2><p>Once you know it&#39;s a real regression, narrow the window:</p><ul><li>The failing execution&#39;s <strong>Verdict</strong> card links back to the <strong>last green run</strong>, so you have two commits to diff between.</li><li>If the drop lines up with a deploy or an infrastructure change, a <a href="/features/timeline-markers.html">timeline marker</a> draws it as a vertical line on the trend chart — &quot;it started the day we switched CI runners&quot; is a much faster answer than a bisect.</li><li>With <a href="/features/ai-diagnosis.html">AI diagnosis</a> configured, the cluster&#39;s explanation is read against your actual git diff since the last green run, and any suggested patch is checked against your source before you see it. Optional, off by default.</li></ul><h2 id="other-ways-to-get-the-same-answer" tabindex="-1">Other ways to get the same answer <a class="header-anchor" href="#other-ways-to-get-the-same-answer" aria-label="Permalink to &quot;Other ways to get the same answer&quot;">​</a></h2><p>Not everyone wants to click through a dashboard mid-review.</p><p><strong>Ask your coding agent.</strong> The <a href="/features/mcp.html">MCP server</a> is built into the running instance — nothing to install. <code>get_run_insights</code> returns the same regression / recovery / new-flaky split this page walks through, and <code>get_test_stability_trend</code> answers &quot;is this getting flakier?&quot; for one test.</p><p><strong>Wire it into CI.</strong> The <a href="/guide/ci.html#blocking-a-merge">CI gate</a> already knows the difference: a test in <a href="/features/flaky-tests.html#quarantine-with-a-way-out">quarantine</a> keeps running and keeps reporting, but doesn&#39;t block the merge — and the gate always states how many failures it excluded.</p><p><strong>Get told instead of looking.</strong> <a href="/features/notifications.html">Notifications</a> let you subscribe to <code>run.failed.default_branch</code> rather than <code>run.failed</code>, so you hear about main going red instead of every red branch build — the difference between an alert people read and one people mute. <code>flakiness.spike</code> fires separately when flakiness crosses your configured threshold.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/features/flaky-tests.html">Flaky tests</a> — how the composite score and root-cause categories are computed</li><li><a href="/guide/concepts.html">Core concepts</a> — <em>test case</em> vs <em>execution</em>, the distinction this recipe leans on</li><li><a href="/features/timeline-markers.html">Timeline markers</a> — correlating a drop with a deploy</li></ul>',22)])])}const w=s(o,[["render",h]]);export{y as __pageData,w as default};
